// Browser core parity + property tests. Run: node --test tests/js/
//
// 1. Golden parity: replays tests/fixtures/browser_golden.json (generated by
//    the real Python pipeline, tests/browser_golden.py) through PostureEngine
//    and requires identical states, nudges, reasons and recovered flags, and
//    metrics / needle within 1e-9.
// 2. DEFAULTS must equal config.yaml (as recorded in the golden file).
// 3. Randomized properties mirroring tests/test_properties.py: bounded needle
//    for arbitrary landmarks, scale invariance, glitch transparency, one
//    chime per bad episode.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

import {
  DEFAULTS, Nudge, PostureEngine, PostureStateMachine, Reason, State, TRACKED,
  NeedleSmoother, rawNeedle, scorePose, scored, unreliable,
} from "../../docs/app/posture-core.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const golden = JSON.parse(
  readFileSync(path.join(here, "..", "fixtures", "browser_golden.json"), "utf8"),
);
const TOL = 1e-9;

function landmarksFrom(encoded) {
  if (encoded === null) return null;
  const lm = Array.from({ length: 33 }, () => ({ x: 0.5, y: 0.5, visibility: 0.9 }));
  TRACKED.forEach((index, i) => {
    const [x, y, v] = encoded[i];
    lm[index] = { x: x === null ? NaN : x, y, visibility: v };
  });
  return lm;
}

function close(a, b, what) {
  if (a === null || b === null) {
    assert.equal(a, b, what);
    return;
  }
  assert.ok(Math.abs(a - b) <= TOL * Math.max(1, Math.abs(b)), `${what}: ${a} vs ${b}`);
}

test("DEFAULTS match config.yaml", () => {
  assert.deepEqual(JSON.parse(JSON.stringify(DEFAULTS)), golden.config);
});

test("golden timeline parity with the Python pipeline", () => {
  const engine = new PostureEngine(golden.config);
  golden.frames.forEach((frame, i) => {
    if (frame.calibrate) engine.calibration.start(frame.calibrate);
    const out = engine.process(landmarksFrom(frame.pose), frame.t);
    const e = frame.expect;
    const where = `frame ${i} t=${frame.t}`;
    assert.equal(out.result.kind, e.kind, `${where} kind`);
    if (e.kind === "scored") {
      const m = out.result;
      [m.head_forward_deg, m.trunk_lean_deg, m.head_tilt_deg, m.shoulder_level_deg]
        .forEach((v, k) => close(v, e.metrics[k], `${where} metric ${k}`));
      assert.equal(m.trunk_lean_available, e.trunk_ok, `${where} trunk_ok`);
    } else {
      assert.equal(out.result.reason, e.reason, `${where} reason`);
      assert.equal(out.result.detail, e.detail, `${where} detail`);
    }
    assert.equal(out.transition.state, e.state, `${where} state`);
    assert.equal(out.transition.nudge, e.nudge, `${where} nudge`);
    assert.equal(out.transition.recovered, e.recovered, `${where} recovered`);
    close(out.needle, e.needle, `${where} needle`);
    assert.deepEqual(out.nudges, e.nudges, `${where} nudges`);
    // Same cue (metric, side and wording) as Python on every frame, and the
    // Python voice reminder spoke exactly that cue.
    const cue = out.cue === null ? null
      : { id: out.cue.id, title: out.cue.title, fix: out.cue.fix, say: out.cue.say };
    assert.deepEqual(cue, e.cue, `${where} cue`);
    if (e.spoken.length) assert.deepEqual(e.spoken, [out.cue.say], `${where} spoken`);
  });
  const cues = new Set(golden.frames.map((f) => f.expect.cue && f.expect.cue.id));
  for (const id of ["head_forward:-", "head_tilt:left", "shoulder_level:right"]) {
    assert.ok(cues.has(id), `golden timeline covers cue ${id}`);
  }
  const all = golden.frames.flatMap((f) => f.expect.nudges);
  assert.ok(all.includes("chime") && all.includes("voice") && all.includes("recovery"));
});

// -- randomized properties (seeded; mirrors tests/test_properties.py) ----------

function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const SPECIAL = [0, -0, 1, -1, 1e308, -1e308, 1.7e308, 5e-324, NaN, Infinity, -Infinity];

function anyFloat(r) {
  const p = r();
  if (p < 0.3) return SPECIAL[Math.floor(r() * SPECIAL.length)];
  if (p < 0.7) return r() * 4 - 2;
  return (r() < 0.5 ? -1 : 1) * 10 ** (r() * 600 - 300);
}

test("P1: needle bounded for arbitrary landmarks and calibrations", () => {
  const r = rng(1);
  for (let n = 0; n < 3000; n += 1) {
    const lm = Array.from({ length: 33 }, () => ({ x: 0.5, y: 0.5, visibility: 0.9 }));
    for (const i of TRACKED) lm[i] = { x: anyFloat(r), y: anyFloat(r), visibility: r() < 0.1 ? NaN : r() };
    const res = scorePose(lm, DEFAULTS.scoring);
    if (res.kind !== "scored") continue;
    for (const k of ["head_forward_deg", "trunk_lean_deg", "head_tilt_deg", "shoulder_level_deg"]) {
      assert.ok(Number.isFinite(res[k]), k);
    }
    const metrics = () => scored({
      head_forward_deg: anyFloat(r), trunk_lean_deg: anyFloat(r), head_tilt_deg: anyFloat(r),
      shoulder_level_deg: anyFloat(r), trunk_lean_available: r() < 0.5,
    });
    const cal = r() < 0.5 ? null : { good: metrics(), bad: metrics() };
    const v = rawNeedle(res, DEFAULTS.scoring, cal);
    assert.ok(v === null || (Number.isFinite(v) && v >= -1 && v <= 1), `needle ${v}`);
  }
  const smoother = new NeedleSmoother({ tau_s: 0.5 });
  for (let n = 0; n < 2000; n += 1) {
    const v = smoother.update(r() < 0.1 ? null : anyFloat(r), anyFloat(r));
    assert.ok(v === null || (Number.isFinite(v) && v >= -1 && v <= 1));
  }
});

// The framing gate measures distance, so it is deliberately not scale
// invariant; open it all the way to test the angles (as test_properties.py does).
const OPEN_FRAMING = { ...DEFAULTS.scoring, shoulder_width_min: 1e-9, shoulder_width_max: 1e9 };

test("P2: angles are scale invariant", () => {
  const r = rng(2);
  const base = { 7: [0.46, 0.45], 8: [0.54, 0.45], 11: [0.40, 0.60], 12: [0.60, 0.60], 23: [0.44, 0.90], 24: [0.56, 0.90] };
  for (let n = 0; n < 1000; n += 1) {
    const k = 10 ** (r() * 6 - 3);
    const a = Array.from({ length: 33 }, () => ({ x: 0.5, y: 0.5, visibility: 1 }));
    const b = Array.from({ length: 33 }, () => ({ x: 0.5, y: 0.5, visibility: 1 }));
    for (const i of TRACKED) {
      const x = base[i][0] + (r() - 0.5) * 0.06;
      const y = base[i][1] + (r() - 0.5) * 0.06;
      a[i] = { x, y, visibility: 1 };
      b[i] = { x: x * k, y: y * k, visibility: 1 };
    }
    const sa = scorePose(a, OPEN_FRAMING);
    const sb = scorePose(b, OPEN_FRAMING);
    for (const key of ["head_forward_deg", "trunk_lean_deg", "head_tilt_deg", "shoulder_level_deg"]) {
      assert.ok(Math.abs(sa[key] - sb[key]) <= 1e-5, `${key} k=${k}`);
    }
  }
});

const GOOD = scored({ head_forward_deg: 0, trunk_lean_deg: 0, head_tilt_deg: 0, shoulder_level_deg: 0 });
const BAD = scored({ head_forward_deg: 18, trunk_lean_deg: 0, head_tilt_deg: 0, shoulder_level_deg: 0 });
const NEUTRAL = scored({ head_forward_deg: 0, trunk_lean_deg: 0, head_tilt_deg: 0, shoulder_level_deg: 4.5 }); // exit 3 < 4.5 < enter 6
const KINDS = [GOOD, BAD, NEUTRAL, unreliable(Reason.NO_POSE), unreliable(Reason.LOW_VISIBILITY),
  unreliable(Reason.NON_FINITE), unreliable(Reason.FRAMING_OUT_OF_BAND, "too far")];

function timeline(r) {
  const out = [];
  let now = 0;
  const dt = 0.02 + r() * 0.48;
  for (let s = 0, segs = 1 + Math.floor(r() * 8); s < segs; s += 1) {
    const result = KINDS[Math.floor(r() * KINDS.length)];
    const end = now + r() * 45;
    while (now <= end) {
      out.push([now, result]);
      now += dt;
    }
  }
  return { out, dt };
}

test("P4: one chime per bad episode, voice spacing respected", () => {
  const r = rng(4);
  for (let n = 0; n < 150; n += 1) {
    const sm = new PostureStateMachine(DEFAULTS.state, DEFAULTS.scoring, DEFAULTS.feedback);
    const { out } = timeline(r);
    let inBad = false, chimes = 0, chimeAt = null, lastVoice = null;
    for (const [now, result] of out) {
      const tr = sm.update(result, now);
      const entering = (tr.state === State.BAD_CHIME || tr.state === State.BAD_VOICE) && !inBad;
      if (entering) { chimes = 0; chimeAt = null; lastVoice = null; }
      if (tr.nudge === Nudge.CHIME) { assert.ok(entering); chimes += 1; chimeAt = now; }
      if (tr.nudge === Nudge.VOICE) {
        assert.ok(chimeAt !== null);
        const gap = lastVoice === null ? now - chimeAt : now - lastVoice;
        const need = lastVoice === null ? DEFAULTS.state.voice_delay_s : DEFAULTS.state.voice_repeat_cooldown_s;
        assert.ok(gap >= need - 1e-6, `voice gap ${gap}`);
        lastVoice = now;
      }
      assert.ok(chimes <= 1);
      inBad = tr.state === State.BAD_CHIME || tr.state === State.BAD_VOICE;
    }
  }
});

test("P5: NaN glitch frames change nothing on the other frames", () => {
  const r = rng(5);
  for (let n = 0; n < 150; n += 1) {
    const { out, dt } = timeline(r);
    const clean = new PostureStateMachine(DEFAULTS.state, DEFAULTS.scoring, DEFAULTS.feedback);
    const glitched = new PostureStateMachine(DEFAULTS.state, DEFAULTS.scoring, DEFAULTS.feedback);
    const every = 1 + Math.floor(r() * 7);
    out.forEach(([now, result], i) => {
      if (i % every === 0) glitched.update(unreliable(Reason.NON_FINITE), now - dt / 2);
      const a = clean.update(result, now);
      const b = glitched.update(result, now);
      assert.deepEqual([b.state, b.nudge, b.recovered], [a.state, a.nudge, a.recovered]);
    });
  }
});
